"use client";
import * as React from "react";
import { cn } from "../lib/cn";

/** Ruimte tussen de kinderen; volgt dezelfde schaal als de rest van de library. */
export type Gap = "none" | "xs" | "sm" | "md" | "lg" | "xl";
export type Align = "start" | "center" | "end" | "stretch" | "baseline";
export type Justify = "start" | "center" | "end" | "between" | "around";

interface GemeenschappelijkeProps {
  gap?: Gap;
  align?: Align;
  justify?: Justify;
  /** Rendert een ander element, bv. "section" of "ul". */
  as?: React.ElementType;
}

export interface ContainerProps extends React.HTMLAttributes<HTMLElement>, GemeenschappelijkeProps {
  /** Maximale breedte; "full" laat de container meegroeien. */
  size?: "sm" | "md" | "lg" | "full";
  /** Binnenmarge links en rechts. */
  padded?: boolean;
}

export interface StackProps extends React.HTMLAttributes<HTMLElement>, GemeenschappelijkeProps {
  /** Scheidingslijn tussen de kinderen. */
  divided?: boolean;
}

export interface RowProps extends React.HTMLAttributes<HTMLElement>, GemeenschappelijkeProps {
  /** Laat de kinderen afbreken naar een volgende regel. */
  wrap?: boolean;
}

export interface GridProps extends React.HTMLAttributes<HTMLElement>, GemeenschappelijkeProps {
  /** Vast aantal kolommen; laat weg voor kolommen die zich vanzelf schikken. */
  cols?: number;
  /** Minimumbreedte per kolom wanneer `cols` niet gezet is. */
  min?: number;
}

export interface SpacerProps extends React.HTMLAttributes<HTMLElement> {
  /** Vaste hoogte of breedte in pixels; zonder waarde duwt de Spacer de rest uit elkaar. */
  size?: number;
  /** Horizontale ruimte in plaats van verticale. */
  horizontal?: boolean;
}

const data = (props: GemeenschappelijkeProps) => ({
  "data-gap": props.gap,
  "data-align": props.align,
  "data-justify": props.justify,
});

/** Container — houdt je inhoud op leesbare breedte en centreert ze. */
export const Container = React.forwardRef<HTMLElement, ContainerProps>(function Container(
  { size = "md", padded = true, gap, align, justify, as: Comp = "div", className, ...rest },
  ref
) {
  return (
    <Comp
      ref={ref}
      data-size={size}
      data-padded={padded ? "" : undefined}
      {...data({ gap, align, justify })}
      className={cn("pxui-container", className)}
      {...rest}
    />
  );
});

/** Stack — kinderen onder elkaar, met één afstand tussen alles. */
export const Stack = React.forwardRef<HTMLElement, StackProps>(function Stack(
  { gap = "md", align, justify, divided, as: Comp = "div", className, ...rest },
  ref
) {
  return (
    <Comp
      ref={ref}
      data-divided={divided ? "" : undefined}
      {...data({ gap, align, justify })}
      className={cn("pxui-stack", className)}
      {...rest}
    />
  );
});

/** Row — kinderen naast elkaar, standaard verticaal gecentreerd. */
export const Row = React.forwardRef<HTMLElement, RowProps>(function Row(
  { gap = "sm", align = "center", justify, wrap = true, as: Comp = "div", className, ...rest },
  ref
) {
  return (
    <Comp
      ref={ref}
      data-wrap={wrap ? "" : undefined}
      {...data({ gap, align, justify })}
      className={cn("pxui-row", className)}
      {...rest}
    />
  );
});

/** Grid — kolommen die zich vanzelf schikken, of een vast aantal. */
export const Grid = React.forwardRef<HTMLElement, GridProps>(function Grid(
  { cols, min = 220, gap = "md", align, justify, as: Comp = "div", className, style, ...rest },
  ref
) {
  return (
    <Comp
      ref={ref}
      {...data({ gap, align, justify })}
      className={cn("pxui-grid", className)}
      style={
        {
          "--pxui-grid-cols": cols ? `repeat(${cols}, minmax(0, 1fr))` : undefined,
          "--pxui-grid-min": `${min}px`,
          ...style,
        } as React.CSSProperties
      }
      {...rest}
    />
  );
});

/** Spacer — duwt wat erna komt weg, of houdt een vaste ruimte vrij. */
export const Spacer = React.forwardRef<HTMLSpanElement, SpacerProps>(function Spacer(
  { size, horizontal, className, style, ...rest },
  ref
) {
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className={cn("pxui-spacer", className)}
      style={{
        flex: size === undefined ? 1 : "none",
        width: horizontal ? size : undefined,
        height: horizontal ? undefined : size,
        ...style,
      }}
      {...rest}
    />
  );
});

/* ============================ Layout ============================ */
/* Eén afstandsschaal voor Stack, Row, Grid en Container. */
.pxui-stack, .pxui-row, .pxui-grid, .pxui-container {
  --pxui-gap: 16px;
  min-width: 0;
}
[data-gap="none"] { --pxui-gap: 0; }
[data-gap="xs"] { --pxui-gap: 6px; }
[data-gap="sm"] { --pxui-gap: 10px; }
[data-gap="md"] { --pxui-gap: 16px; }
[data-gap="lg"] { --pxui-gap: 24px; }
[data-gap="xl"] { --pxui-gap: 36px; }

.pxui-stack { display: flex; flex-direction: column; gap: var(--pxui-gap); }
.pxui-row { display: flex; flex-direction: row; gap: var(--pxui-gap); }
.pxui-row[data-wrap] { flex-wrap: wrap; }
.pxui-grid {
  display: grid; gap: var(--pxui-gap);
  grid-template-columns: var(--pxui-grid-cols, repeat(auto-fit, minmax(min(var(--pxui-grid-min, 220px), 100%), 1fr)));
}

.pxui-stack[data-align="start"], .pxui-row[data-align="start"], .pxui-grid[data-align="start"] { align-items: flex-start; }
.pxui-stack[data-align="center"], .pxui-row[data-align="center"], .pxui-grid[data-align="center"] { align-items: center; }
.pxui-stack[data-align="end"], .pxui-row[data-align="end"], .pxui-grid[data-align="end"] { align-items: flex-end; }
.pxui-stack[data-align="stretch"], .pxui-row[data-align="stretch"], .pxui-grid[data-align="stretch"] { align-items: stretch; }
.pxui-stack[data-align="baseline"], .pxui-row[data-align="baseline"] { align-items: baseline; }

[data-justify="start"] { justify-content: flex-start; }
[data-justify="center"] { justify-content: center; }
[data-justify="end"] { justify-content: flex-end; }
[data-justify="between"] { justify-content: space-between; }
[data-justify="around"] { justify-content: space-around; }

/* Scheidingslijnen tussen de kinderen van een Stack. */
.pxui-stack[data-divided] > * + * {
  border-top: 1px solid var(--border);
  padding-top: var(--pxui-gap);
}

.pxui-container { width: 100%; margin-inline: auto; }
.pxui-container[data-size="sm"] { max-width: 640px; }
.pxui-container[data-size="md"] { max-width: var(--maxw); }
.pxui-container[data-size="lg"] { max-width: 1400px; }
.pxui-container[data-size="full"] { max-width: none; }
.pxui-container[data-padded] { padding-inline: 20px; }
@media (max-width: 640px) { .pxui-container[data-padded] { padding-inline: 16px; } }

.pxui-spacer { display: block; }
